pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testFuzz_property(address account) public {
        vm.assume(account != address(0));
        uint256 amount = 1 ether;
        vm.deal(account, amount);
        vm.prank(account);
        (bool ok,) = address(c).call{value: amount}("");
        require(ok, "deposit failed");
        vm.prank(account);
        c.withdraw();
        uint256 balAfter = c.balances(account);
        assertTrue(balAfter == 0);
    }
}
